const slug = ($json.project_slug ?? $json['Project Slug'] ?? '').toString().trim().toLowerCase().replace(/[^a-z0-9-]/g, '');
if (!slug) throw new Error('Project Slug is required.');
const regenRaw = ($json.regen_ids ?? $json['Shot IDs to Regenerate (optional)'] ?? '').toString();
const regenIds = regenRaw.split(/[,\s]+/).map((x) => x.trim().toLowerCase()).filter(Boolean);
const modelRaw = ($json.tts_model ?? $json['TTS Model'] ?? 'auto (from script)').toString();
let model = 'auto';
if (modelRaw === 'gpt-4o-mini-tts') model = 'gpt-4o-mini-tts';
else if (modelRaw === 'tts-1') model = 'tts-1';
return [{ json: { slug, payloadB64: Buffer.from(JSON.stringify({ slug, regen_ids: regenIds, tts_model: model })).toString('base64') } }];

const res = JSON.parse(($json.stdout ?? '').toString().trim());
if (!res.ok) throw new Error(res.error || 'Failed to load TTS lines.');
if (!res.lines.length) throw new Error('All voiceover audio already exists. Enter shot ids in the form to force regeneration.');
return [{ json: { slug: res.slug, lines: res.lines } }];

const srcs = $('Split Lines').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const line = srcs[i].json;
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  if (!buf || !buf.length) throw new Error('No audio returned for line ' + (line.lineId ?? i));
  const destDir = '/home/node/files/films/' + line.slug + '/audio/lines';
  const destPath = destDir + '/' + line.lineId + '.mp3';
  const b64 = buf.toString('base64');
  const SIZE = 60000;
  const nChunks = Math.max(1, Math.ceil(b64.length / SIZE));
  for (let s = 0; s < nChunks; s++) {
    out.push({ json: {
      fileId: line.slug + '_' + line.lineId, destDir, destPath, seq: s,
      isLast: (s === nChunks - 1) ? 1 : 0,
      chunkB64: b64.slice(s * SIZE, (s + 1) * SIZE),
    }});
  }
}
return out;
